`timescale 1ns/10ps
`default_nettype wire
// Self-check testbench: drives your pwm_gen with a fixed random stimulus and compares every output against
// known-correct values recorded from the reference implementation (X bits of the reference are not checked).
// Do not edit this file or tb_selfcheck_vectors.vh.  Prints PASS, or FAIL lines for the first mismatches.
module tb_selfcheck;
    integer seed, seed0, errs, checks, known, cyc, cycles;
    reg  clk = 0;
    reg  reset = 0;
    reg  en = 0;
    reg  [7:0] duty = 0;
    wire dut_pwm;
    wire dut_period_start;
    pwm_gen #(.PRE(1)) dut (.clk(clk), .reset(reset), .en(en), .duty(duty), .pwm(dut_pwm), .period_start(dut_period_start));
    function [31:0] r32(input integer dummy); begin r32 = $random(seed); end endfunction
    function [63:0] r64(input integer dummy); begin r64 = {$random(seed), $random(seed)}; end endfunction
    // chance(n): true with probability n/256
    function chance(input integer n); reg [7:0] v; begin v = $random(seed); chance = (v < n); end endfunction

    initial begin #(0); forever #(5) clk = ~clk; end
    always @(posedge clk) cyc <= cyc + 1;
    always @(negedge clk) begin
        reset <= ((r32(0) % 4096) == 0);
        if (chance(4)) en <= ~en;
        if (chance(8)) duty <= r32(0);
    end
    reg [1:0] sc_cur;
    integer sc_ptr, sc_sptr, kn_t, sc_k, sc_first; reg bad_t;
    integer sc_nerr [0:5]; integer sc_fcyc [0:5];   // per signal: mismatching sample points, first cycle
    reg [5:0] sc_badv;
    reg [20:0] sc_exp_s;
`include "tb_selfcheck_vectors.vh"
    task automatic cmp_bits_(input [1023:0] g, input [1023:0] c, input integer w, output reg bad, output integer kn);
        integer i;
        begin bad = 0; kn = 0;
            if (g === c) begin if (^g[1023:0] !== 1'bx) kn = w; end
            else for (i = 0; i < w; i = i + 1) if (g[i] === 1'b0 || g[i] === 1'b1) begin
                kn = kn + 1; if (c[i] !== g[i]) bad = 1; end
        end
    endtask
    task show_first; integer sh; begin
        $display("FAIL: first mismatch at cycle %0d (sample point %0d); every value below is from that sample point", cyc, checks);
        $display("FAIL:   inputs reset=%h en=%h duty=%h", reset, en, duty);
        sh = 0;
        if (sc_badv[0]) begin if (sh < 6) $display("FAIL:   output pwm expected %h got %h (wrong bits %h)", sc_cur[1:1], dut_pwm, sc_cur[1:1] ^ dut_pwm); sh = sh + 1; end
        if (sc_badv[1]) begin if (sh < 6) $display("FAIL:   output period_start expected %h got %h (wrong bits %h)", sc_cur[0:0], dut_period_start, sc_cur[0:0] ^ dut_period_start); sh = sh + 1; end
        if (sc_badv[2]) begin if (sh < 6) $display("FAIL:   state pre_cnt expected %h got %h (wrong bits %h)", sc_exp_s[20:17], dut.pre_cnt, sc_exp_s[20:17] ^ dut.pre_cnt); sh = sh + 1; end
        if (sc_badv[3]) begin if (sh < 6) $display("FAIL:   state tick expected %h got %h (wrong bits %h)", sc_exp_s[16:16], dut.tick, sc_exp_s[16:16] ^ dut.tick); sh = sh + 1; end
        if (sc_badv[4]) begin if (sh < 6) $display("FAIL:   state cnt expected %h got %h (wrong bits %h)", sc_exp_s[15:8], dut.cnt, sc_exp_s[15:8] ^ dut.cnt); sh = sh + 1; end
        if (sc_badv[5]) begin if (sh < 6) $display("FAIL:   state duty_q expected %h got %h (wrong bits %h)", sc_exp_s[7:0], dut.duty_q, sc_exp_s[7:0] ^ dut.duty_q); sh = sh + 1; end
        if (sh > 6) $display("FAIL:   (%0d more signals differ at this sample point)", sh - 6);
        sh = 0; $write("FAIL:   outputs that match here:");
        if (!sc_badv[0]) begin if (sh < 10) $write(" pwm=%h", dut_pwm); sh = sh + 1; end
        if (!sc_badv[1]) begin if (sh < 10) $write(" period_start=%h", dut_period_start); sh = sh + 1; end
        if (sh > 10) $write(" (+%0d more)", sh - 10);
        $display("");
    end endtask
    task check; begin
        while (sc_ptr + 1 < SC_NEV && sc_ev_k[sc_ptr + 1] <= checks) sc_ptr = sc_ptr + 1;
        sc_cur = sc_ev_v[sc_ptr];
        while (sc_sptr + 1 < SC_NSEV && sc_sev_k[sc_sptr + 1] <= checks) sc_sptr = sc_sptr + 1;
        sc_exp_s = sc_sev_v[sc_sptr];
        sc_badv = 0;
        cmp_bits_(sc_cur[1:1], dut_pwm, 1, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[0] = 1'b1; if (sc_nerr[0] == 0) sc_fcyc[0] = cyc; sc_nerr[0] = sc_nerr[0] + 1; end
        cmp_bits_(sc_cur[0:0], dut_period_start, 1, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[1] = 1'b1; if (sc_nerr[1] == 0) sc_fcyc[1] = cyc; sc_nerr[1] = sc_nerr[1] + 1; end
        cmp_bits_(sc_exp_s[20:17], dut.pre_cnt, 4, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[2] = 1'b1; if (sc_nerr[2] == 0) sc_fcyc[2] = cyc; sc_nerr[2] = sc_nerr[2] + 1; end
        cmp_bits_(sc_exp_s[16:16], dut.tick, 1, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[3] = 1'b1; if (sc_nerr[3] == 0) sc_fcyc[3] = cyc; sc_nerr[3] = sc_nerr[3] + 1; end
        cmp_bits_(sc_exp_s[15:8], dut.cnt, 8, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[4] = 1'b1; if (sc_nerr[4] == 0) sc_fcyc[4] = cyc; sc_nerr[4] = sc_nerr[4] + 1; end
        cmp_bits_(sc_exp_s[7:0], dut.duty_q, 8, bad_t, kn_t); known = known + kn_t;
        if (bad_t) begin errs = errs + 1; sc_badv[5] = 1'b1; if (sc_nerr[5] == 0) sc_fcyc[5] = cyc; sc_nerr[5] = sc_nerr[5] + 1; end
        if (sc_badv != 0 && !sc_first) begin sc_first = 1; show_first; end
        checks = checks + 1;
    end endtask
    task summary; integer sh; begin
        sh = 0;
        if (sc_nerr[0] != 0) begin if (sh < 5) $display("FAIL: output pwm: %0d mismatching sample points, first at cycle %0d", sc_nerr[0], sc_fcyc[0]); sh = sh + 1; end
        if (sc_nerr[1] != 0) begin if (sh < 5) $display("FAIL: output period_start: %0d mismatching sample points, first at cycle %0d", sc_nerr[1], sc_fcyc[1]); sh = sh + 1; end
        if (sc_nerr[2] != 0) begin if (sh < 5) $display("FAIL: state pre_cnt: %0d mismatching sample points, first at cycle %0d", sc_nerr[2], sc_fcyc[2]); sh = sh + 1; end
        if (sc_nerr[3] != 0) begin if (sh < 5) $display("FAIL: state tick: %0d mismatching sample points, first at cycle %0d", sc_nerr[3], sc_fcyc[3]); sh = sh + 1; end
        if (sc_nerr[4] != 0) begin if (sh < 5) $display("FAIL: state cnt: %0d mismatching sample points, first at cycle %0d", sc_nerr[4], sc_fcyc[4]); sh = sh + 1; end
        if (sc_nerr[5] != 0) begin if (sh < 5) $display("FAIL: state duty_q: %0d mismatching sample points, first at cycle %0d", sc_nerr[5], sc_fcyc[5]); sh = sh + 1; end
        if (sh > 5) $display("FAIL: (%0d more signals fail)", sh - 5);
        sh = 0; $write("  pass: outputs that match at every sample point:");
        if (sc_nerr[0] == 0) begin if (sh < 12) $write(" pwm"); sh = sh + 1; end
        if (sc_nerr[1] == 0) begin if (sh < 12) $write(" period_start"); sh = sh + 1; end
        if (sh == 0) $write(" none"); if (sh > 12) $write(" (+%0d more)", sh - 12);
        $display("");
    end endtask
    initial begin
        errs = 0; checks = 0; known = 0; cyc = 0;
        sc_ptr = 0; sc_sptr = 0; sc_first = 0;
        for (sc_k = 0; sc_k < 6; sc_k = sc_k + 1) begin sc_nerr[sc_k] = 0; sc_fcyc[sc_k] = -1; end
        seed = 9001;
        cycles = 8000;
        seed0 = seed;
        reset = 1'b0;
        en = 1'b1;
        duty = 8'd0;
        #(0.5);
        while (cyc < cycles) begin check; #(1.0); end
        if (checks != SC_NCHECKS) begin errs = errs + 1;
            $display("FAIL: testbench ran %0d checks, the vectors hold %0d", checks, SC_NCHECKS); end
        if (errs == 0) begin
            $display("selfcheck: seed 9001, %0d cycles, %0d sample points, %0d known output bits compared", cyc, checks, known);
            $display("PASS");
        end else begin summary; $display("FAIL: %0d mismatches", errs); end
        $finish;
    end
endmodule
